<template>
  <section class="cooking-panel">
    <div class="cooking-heading"><span class="section-kicker">На вашей кухне</span><h2>Сколько готовим?</h2><p>Меняйте число порций — весь список ингредиентов пересчитается.</p></div>
    <div class="batch-control"><div class="batch-stepper"><button aria-label="Готовить на одну порцию меньше" :disabled="count <= 1" @click="setCount(count - 1)">−</button><input :value="count" type="number" min="1" max="50" aria-label="Порций для приготовления" @change="setCountFromInput" /><button aria-label="Готовить на одну порцию больше" :disabled="count >= 50" @click="setCount(count + 1)">+</button><span>порций</span></div><div class="batch-presets"><button v-for="n in [1, 2, 4, 6]" :key="n" :class="{ active: count === n }" :aria-pressed="count === n" @click="setCount(n)">{{ n }}</button></div></div>
    <div class="mobile-portion-nutrition"><strong>{{ Math.round(perServing.calories) }} ккал / порция</strong><span>Б {{ numberText(perServing.protein) }} · Ж {{ numberText(perServing.fat) }} · У {{ numberText(perServing.carbs) }} г</span></div>
    <div class="cooking-summary"><span>{{ cookingModes.find(m => m.value === recipe.cookingMode)?.title || 'Рецепт' }}</span><span v-if="totalTime">≈ {{ totalTime }} мин на исходные {{ recipe.servings }} порц.</span><span v-if="recipe.freezerFriendly">Можно заморозить</span></div>
    <div class="cooking-ingredients"><div class="cooking-labels"><h3>Ингредиенты на {{ count }} порц.</h3><span>{{ recipe.ingredients?.length || 0 }} продуктов</span></div><div v-for="ing in recipe.ingredients" :key="ing.productId" class="cooking-ingredient"><div><strong>{{ productLabel(ing.product) }}</strong><small>{{ stateLabel(ing.product) }}<span v-if="ing.product?.unitType === 'piece'"> · съедобная часть</span></small></div><div class="cooking-amount"><strong>{{ ingredientAmount(ing, factor) }}</strong><small v-if="ing.product?.unitType === 'piece'">≈ {{ numberText(ing.weight * factor) }} г</small></div></div><p v-if="!recipe.ingredients?.length" class="cooking-hint">Добавьте состав, чтобы рассчитать порции.</p></div>
    <div v-if="recipe.batchNotes" class="batch-note"><v-icon icon="mdi-calendar-check" size="21" /><div><h3>Что сделать заранее</h3><p>{{ recipe.batchNotes }}</p></div></div>
    <div class="cooking-method"><h3>Как приготовить</h3><ol v-if="recipe.instructions?.length"><li v-for="(step, index) in recipe.instructions" :key="index"><span>{{ index + 1 }}</span><p>{{ step }}</p></li></ol><p v-else class="cooking-hint">{{ recipe.description ? 'Посмотрите описание блюда выше. Отдельные шаги приготовления пока не добавлены.' : 'Добавьте шаги приготовления в настройках своего рецепта.' }}</p></div>
    <div v-if="recipe.ingredients?.length" class="portion-weighing"><h3>Разделить готовое блюдо по весу</h3><p>Взвесьте готовую основу без посуды и разделите на порции. Фрукты, соусы и гарнир, которые подаёте отдельно, делите отдельно. После варки вес меняется из-за воды.</p><v-text-field v-model.number="measuredWeight" label="Вес готовой партии, г" type="number" min="1" max="100000" step="any" clearable hide-details /><div v-if="validMeasuredWeight" class="weighing-result" aria-live="polite"><strong>{{ numberText(Number(measuredWeight) / count) }} г на порцию</strong></div><p v-else-if="measuredWeight !== null && measuredWeight !== ''" class="cooking-hint">Укажите вес от 1 до 100 000 г.</p><small>Измерение для этой готовки. При изменении числа порций введите новый вес. Компоненты, которые подаёте отдельно, делите отдельно.</small></div>
    <div v-if="recipe.storageInstructions || recipe.storageDays != null" class="storage-note"><h3>Хранение<span v-if="recipe.storageDays != null">{{ recipe.storageDays === 0 ? 'Подавать сразу' : `До ${recipe.storageDays * 24} часов в холодильнике` }}</span></h3><p>{{ recipe.storageInstructions || 'Учитывайте сроки каждого ингредиента после вскрытия.' }}</p><p v-if="recipe.isBase" class="storage-source">Общие правила: <a href="https://www.gov.uk/government/publications/cooking-your-food/cooking-your-food" target="_blank" rel="noopener noreferrer">Food Standards Agency ↗</a><a v-if="hasRice" href="https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker" target="_blank" rel="noopener noreferrer">Правила для риса ↗</a></p></div>
    <p class="cooking-footnote">Количество для приготовления не меняет сохранённый рецепт и меню. В плане недели используйте состав и порцию, рассчитанные для конкретного приёма пищи.</p>
  </section>
</template>
<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import type { Recipe } from '~/composables/useApi'
import { productLabel, stateLabel, ingredientAmount, numberText, cookingModes, recipeNutrition } from '~/utils/food'
const props = defineProps<{ recipe: Recipe }>()
const count = ref(props.recipe.servings || 1)
const measuredWeight = ref<number | string | null>(props.recipe.cookedWeight || null)
const factor = computed(() => count.value / (props.recipe.servings || 1))
const perServing = computed(() => recipeNutrition(props.recipe.ingredients || [], props.recipe.servings || 1))
const totalTime = computed(() => (props.recipe.prepMinutes || 0) + (props.recipe.cookMinutes || 0))
const hasRice = computed(() => props.recipe.ingredients?.some(i => /^Рис /.test(i.product?.name || '')))
const validMeasuredWeight = computed(() => typeof measuredWeight.value === 'number' && Number.isFinite(measuredWeight.value) && measuredWeight.value >= 1 && measuredWeight.value <= 100000)
const setCount = (n: number) => { count.value = Number.isFinite(n) ? Math.min(50, Math.max(1, Math.round(n))) : 1 }
const setCountFromInput = (event: Event) => {
  const input = event.target as HTMLInputElement
  setCount(Number(input.value))
  input.value = String(count.value)
}
watch(count, () => { measuredWeight.value = null }, { flush: 'sync' })
watch([() => props.recipe.id, () => props.recipe.servings, () => props.recipe.cookedWeight], () => { count.value = props.recipe.servings || 1; measuredWeight.value = props.recipe.cookedWeight || null })
</script>
