g { display:block; color:#41593a; font-size:13px; font-weight:500; }.cooking-ingredient small { display:block; margin-top:5px; color: var(--text-secondary); font-size: 12px; }.cooking-amount { text-align:right; flex-shrink:0; }.cooking-amount strong { font-size:16px; font-variant-numeric:tabular-nums; }.batch-note { display:flex; gap:14px; margin:0 30px 30px; padding:20px; background:#f6f3e9; border-radius:14px; color: var(--text-secondary); }.batch-note p,.cooking-method p,.storage-note p,.portion-weighing p { color: var(--text-secondary); font-size:13px; line-height:1.85; margin-top:8px; }.cooking-method { padding:0 30px 25px; }.cooking-method ol { list-style:none; padding:4px 0 0; }.cooking-method li { display:flex; align-items:baseline; gap:15px; margin-top:18px; }.cooking-method li>span { flex-shrink:0; background:#edf2e3; color:#45603b; display:grid; place-items:center; width:27px; height:27px; border-radius:50%; font-size:11px; }.cooking-method li p { margin:0; }.portion-weighing { padding:25px 30px; border-block:1px solid #e5ebdc; background:#fbfcf8; }.portion-weighing .v-text-field { max-width:300px; margin:18px 0 13px; }.portion-weighing>small { display:block; color: var(--text-secondary); font-size: 12px; line-height:1.7; }.weighing-result { display:flex; flex-wrap:wrap; align-items:baseline; gap:8px 15px; color:#42613c; margin:13px 0; }.weighing-result>span { font-size:11px; }.storage-note { padding:26px 30px; }.storage-note h3 span { display:block; font-size:11px; font-weight:400; color: var(--text-secondary); margin-top:9px; }.storage-note .storage-source { font-size: 12px; }.storage-source a { color: var(--text-secondary); margin-right:10px; }.cooking-footnote { padding:0 30px 26px; color: var(--text-secondary); font-size: 12px; line-height:1.8; }button:disabled { opacity:.4; }@media(max-width:650px) { .cooking-heading,.cooking-method,.portion-weighing,.storage-note { padding-left:18px; padding-right:18px; }.batch-control,.cooking-ingredients,.batch-note { margin-left:18px; margin-right:18px; }.batch-control { flex-wrap:wrap; justify-content:center; padding:14px; }.cooking-summary,.cooking-footnote { padding-left:18px; padding-right:18px; }.cooking-summary span+span::before { display:none; }.cooking-ingredient { gap:10px; }.cooking-ingredient strong { font-size:12px; }.cooking-amount strong { font-size:15px; } }
</style>
